parameters.jsonOutput:
={{ JSON.stringify((() => {
  const S = $('Settings').first().json;
  const r = $json.row ?? $json;
  const t = (v) => String(v ?? '').trim();
  const allowed = String(S.allowed_currencies).split(',').map((x) => x.trim().toUpperCase());
  const moneyOk = (v) => /^-?\d+(\.\d{1,2})?$/.test(t(v));
  const dateOk = (v) => /^\d{4}-\d{2}-\d{2}$/.test(t(v)) && DateTime.fromISO(t(v), { zone: 'utc' }).isValid;
  const minor = (v) => moneyOk(v) ? Math.round(Number(t(v)) * 100) : 0;
  const inv = t(r.invoice_no);
  const cur = t(r.currency).toUpperCase();
  const docType = t(r.doc_type).toLowerCase();
  const status = t(r.status).toLowerCase();
  const dup = $('Split invoices').all().filter((x) => t((x.json.row ?? x.json).invoice_no) === inv).length > 1;
  const am = minor(r.amount);
  const pm = minor(r.amount_paid);
  const bm = minor(r.balance);
  let bad = '';
  if (inv === '') bad = 'missing_invoice_no';
  else if (dup) bad = 'duplicate_invoice_no';
  else if (!moneyOk(r.amount) || !moneyOk(r.amount_paid) || !moneyOk(r.balance)) bad = 'bad_money';
  else if (!dateOk(r.issue_date) || !dateOk(r.due_date) || (t(r.paid_date) !== '' && !dateOk(r.paid_date))) bad = 'bad_date';
  else if (!allowed.includes(cur)) bad = 'bad_currency';
  else if (!['invoice', 'credit_note'].includes(docType) || !['open', 'paid', 'void'].includes(status)) bad = 'bad_type_or_status';
  else if (status !== 'void' && bm !== am - pm) bad = 'balance_mismatch';
  else if (docType === 'invoice' && bm < 0) bad = 'negative_balance';
  return {
    invoice_no: inv, doc_type: docType, status: status,
    customer_name: t(r.customer_name).replace(/\s+/g, ' '), customer_email: t(r.customer_email),
    issue_date: t(r.issue_date), due_date: t(r.due_date), paid_date: t(r.paid_date), currency: cur,
    amount_minor: am, paid_minor: pm, balance_minor: bm,
    email_usable: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(t(r.customer_email)),
    bad_reason: bad, row_valid: bad === ''
  };
})()) }}
